export function AnimClappingHand_Step(sprite: any): any {
  if (sprite.data[2] == 0)
      {
          sprite.x2 += sprite.data[1];
          if (sprite.x2 == 0)
          {
              sprite.data[2]++;
              if (sprite.data[3] == 0)
              {
                  PlaySE1WithPanning(SE_M_ENCORE, BattleAnimAdjustPanning(SOUND_PAN_ATTACKER));
              }
          }
      }
      else
      {
          sprite.x2 -= sprite.data[1];
          if (abs(sprite.x2) == 12)
          {
              sprite.data[0]--;
              sprite.data[2]--;
          }

      }

      if (sprite.data[0] == 0)
          DestroyAnimSprite(sprite);
}

