/** static void TormentAttacker_Step(u8 taskId) */
export function TormentAttacker_Step(taskId: any): any {
  let var0, var1;
      let x, y;
      let i, j;
      let spriteId: any = null;
      let task: any =gTasks[taskId];

      switch (task.data[0])
      {
      case 0:
          var0 = task.data[2];
          if (task.data[1] & 1)
          {
              var1 = task.data[4];
              x = var0 - var1;
          }
          else
          {
              var1 = task.data[4];
              x = var0 + var1;
          }

          y = task.data[3] + task.data[5];
          spriteId = CreateSprite(gThoughtBubbleSpriteTemplate, x, y, 6 - task.data[1]);
          PlaySE12WithPanning(SE_M_METRONOME, BattleAnimAdjustPanning(SOUND_PAN_ATTACKER));

          if (spriteId != MAX_SPRITES)
          {
              gSprites[spriteId].hFlip = task.data[1] & 1;
              gSprites[spriteId].callback = SpriteCallbackDummy;
          }

          if (task.data[1] & 1)
          {
              task.data[4] -= 6;
              task.data[5] -= 6;
          }

          PrepareAffineAnimInTaskData(task, task.data[15], sAffineAnims_Torment);
          task.data[1]++;
          task.data[0] = 1;
          break;
      case 1:
          if (!RunAffineAnimFromTaskData(task))
          {
              if (task.data[1] == 6)
              {
                  task.data[6] = 8;
                  task.data[0] = 3;
              }
              else
              {
                  if (task.data[1] <= 2)
                      task.data[6] = 10;
                  else
                      task.data[6] = 0;

                  task.data[0] = 2;
              }
          }
          break;
      case 2:
          if (task.data[6] != 0)
              task.data[6]--;
          else
              task.data[0] = 0;
          break;
      case 3:
          if (task.data[6] != 0)
              task.data[6]--;
          else
              task.data[0] = 4;
          break;
      case 4:
          for (i = 0, j = 0; i < MAX_SPRITES; i++)
          {
              if (gSprites[i].template ==gThoughtBubbleSpriteTemplate)
              {
                  gSprites[i].data[0] = taskId;
                  gSprites[i].data[1] = 6;
                  StartSpriteAnim(gSprites[i], 2);
                  gSprites[i].callback = TormentAttacker_Callback;

                  if (++j == 6)
                      break;
              }
          }

          task.data[6] = j;
          task.data[0] = 5;
          break;
      case 5:
          if (task.data[6] == 0)
              DestroyAnimVisualTask(taskId);
          break;
      }
}

/** static void TormentAttacker_Callback(struct Sprite *sprite) */
export function TormentAttacker_Callback(sprite: any): any {
  if (sprite.animEnded)
      {
          gTasks[sprite.data[0]].data[sprite.data[1]]--;
          DestroySprite(sprite);
      }
}

/** static void AnimTriAttackTriangle(struct Sprite *sprite) */
export function AnimTriAttackTriangle(sprite: any): any {
  if (sprite.data[0] == 0)
          InitSpritePosToAnimAttacker(sprite, FALSE);

      if (++sprite.data[0] < 40)
      {
          let _var: any = sprite.data[0];
          if ((_var & 1) == 0)
              sprite.invisible = TRUE;
          else
              sprite.invisible = FALSE;
      }

      if (sprite.data[0] > 30)
          sprite.invisible = FALSE;

      if (sprite.data[0] == 61)
      {
          StoreSpriteCallbackInData6(sprite, DestroyAnimSprite);
          sprite.x += sprite.x2;
          sprite.y += sprite.y2;
          sprite.x2 = 0;
          sprite.y2 = 0;
          sprite.data[0] = 20;
          sprite.data[2] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2);
          sprite.data[4] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET);
          sprite.callback = StartAnimLinearTranslation;
      }
}

