          if (!IsContest())
              SetAnimBgAttribute(1, BG_ANIM_CHAR_BASE_BLOCK, 0);

          SetAnimBgAttribute(1, BG_ANIM_PRIORITY, 1);
          gBattle_BG1_X = 0;
          gBattle_BG1_Y = 0;
          SetGpuReg(REG_OFFSET_BLDCNT, 0);
          SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          DestroyAnimVisualTask(taskId);
          break;
